function kimpu_customizer_page_choices() { $choices = array( 0 => __( '— Select a page —', 'kimpu-multipurpose' ) ); foreach ( get_pages( array( 'sort_column' => 'post_title', 'post_status' => 'publish' ) ) as $page ) { $choices[ $page->ID ] = $page->post_title; } return $choices; }
